    public static void register(EntityRenderersEvent.RegisterLayerDefinitions event) {
        event.registerLayerDefinition(BRAMBLE_SENTINEL, MobModels::bramble_sentinel);
        event.registerLayerDefinition(SPORECAP, MobModels::sporecap);
        event.registerLayerDefinition(ROOTSTALKER, MobModels::rootstalker);
        event.registerLayerDefinition(CALCITE_SENTINEL, MobModels::calcite_sentinel);
        event.registerLayerDefinition(STORM_WISP, MobModels::storm_wisp);
        event.registerLayerDefinition(GALE_TALON, MobModels::gale_talon);
        event.registerLayerDefinition(ASHBOUND_KNIGHT, MobModels::ashbound_knight);
        event.registerLayerDefinition(SOUL_JAILER, MobModels::soul_jailer);
        event.registerLayerDefinition(CINDER_HOUND, MobModels::cinder_hound);
        event.registerLayerDefinition(MOSSBACK_TITAN, MobModels::mossback_titan);
        event.registerLayerDefinition(TEMPEST_ROC, MobModels::tempest_roc);
        event.registerLayerDefinition(HOLLOW_KING, MobModels::hollow_king);
    }
